window.docContents[40].resolve({"/rules/RG1004/#RG1004-proof-shape":{"contents":"The replacement proof proves the same proposition. Kernel reduction (decide, rfl) is permitted, subject to the surface's foundation profile.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1004: Compiler-trusting proofs require separate classification","header":"Required proof shape","id":"/rules/RG1004/#RG1004-proof-shape"},"/rules/RG2003/#RG2003-proof-shape":{"contents":"The fix must not change the proposition or behavior being claimed; if it does, review the statement again.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2003: Claimed source must elaborate warning-free","header":"Required proof shape","id":"/rules/RG2003/#RG2003-proof-shape"},"/rules/RG3002/#RG3002-proof-shape":{"contents":"∀ xs, f.{us} xs = g.{us} xs over the reference's complete dependent domain, closed, with no additional hypotheses, admitted by the kernel. An actual domain hypothesis is legitimate; an extra premise such as False is not.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG3002: Checked execution requires admitted correspondence","header":"Required proof shape","id":"/rules/RG3002/#RG3002-proof-shape"},"/rules/RG4001/#RG4001-proof-shape":{"contents":"No proof obligation: the rule concerns document structure. Each classified fence is then checked by RG4002, RG4003 or RG4004.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4001: Documentation fences must have a valid classification","header":"Required proof shape","id":"/rules/RG4001/#RG4001-proof-shape"}});